  "settings.sandboxProfile": "沙箱設定檔",
  "settings.sandboxProfileDesc":
    "對 Agent 行程施加作業系統級檔案系統/網路隔離（Linux Landlock / macOS Seatbelt）。在新啟動 Agent 時生效——變更後請重新連線工作階段。可在專案選單中為單一專案覆寫。",
  "settings.sandbox.off": "關閉 — 無限制",
