  "automations.launchAgent.failReveal":
    "無法開啟助手檔案目錄。可先產生/啟用一次助手，或檢查應用資料目錄權限。",
  "automations.launchAgent.failHonesty":
    "此助手不是背景排程守護行程。即便安裝成功，任務仍只在完整 Grok 應用行程內（視窗或系統匣）觸發。正常結束仍會暫停排程。",
