  "settings.remoteIm.weixin.allowFromHelp": "允許與機器人對話的使用者 ID。僅測試時可使用 *，生產環境建議改為明確微信使用者 ID。",
  "settings.remoteIm.weixin.accountIdHelp": "多實例綁定時的本機帳號標籤（預設 default）。",
  "settings.remoteIm.weixin.routeTagHelp": "可選 SKRouteTag 請求標頭（多路由部署）。一般留空。",
