  "settings.remoteIm.weixin.chatIdHelp": "可選綁定群 chat_id。空=全部工作階段。群聊房間通常以 @chatroom 結尾。",
  "settings.remoteIm.weixin.proxyHelp": "可選 HTTP/SOCKS5 代理，用於 ilink 長輪詢 / 傳送。留空則使用應用代理或直連。",
