  "settings.remoteIm.telegram.tokenPlaceholder": "123456789:AAH…",
  "settings.remoteIm.telegram.proxyHelp": "可選 HTTP/SOCKS5 代理，用於 Telegram API（getUpdates / 傳送）。留空則使用應用代理或直連。",
  "settings.remoteIm.telegram.proxyPlaceholder": "socks5://127.0.0.1:1080",
  "settings.remoteIm.telegram.proxyUserHelp": "代理需要驗證時的使用者名稱（可選）。",
  "settings.remoteIm.telegram.proxyPassHelp": "代理密碼（可選）。預設遮罩儲存。",
  "settings.remoteIm.telegram.threadHelp": "開啟後依論壇話題 / thread 隔離 Agent 工作階段（每話題獨立上下文）。",
  "settings.remoteIm.telegram.guide.title": "Telegram 接入",
  "settings.remoteIm.telegram.guide.step1": "在 Telegram 開啟 @BotFather，執行 /newbot（或選擇既有機器人），複製 Bot Token。",
  "settings.remoteIm.telegram.guide.step2": "將 Token 貼到此處。長輪詢無需公網 URL，不需要設定 Webhook。",
  "settings.remoteIm.telegram.guide.step3": "可選填寫 HTTP/SOCKS 代理，限制 allow-from（生產環境避免 *），再點「儲存並連線」。",
  "settings.remoteIm.telegram.guide.softFail": "「測試連線」會校驗 Token 格式，並在可連網時呼叫 getMe — 不代表 getUpdates 已在輪詢，需 Bridge 執行且實例已連結。",
  "settings.remoteIm.telegram.err.tokenFormat": "Bot Token 格式無效。請貼上 @BotFather 的完整 token（數字:字母數字）。",
  "settings.remoteIm.telegram.err.proxy": "代理 URL 無效。請使用 http://、https://、socks5:// 或 socks5h://，並包含主機與埠。",
  "settings.remoteIm.line.channelSecretHelp": "來自 LINE Developers 控制台（Messaging API）的 Channel Secret。預設遮罩儲存，不入日誌。",
  "settings.remoteIm.line.channelSecretPlaceholder": "Channel secret…",
