  "settings.remoteIm.line.portPlaceholder": "8081",
  "settings.remoteIm.line.callbackPathHelp": "本機回呼路徑（預設 /line/callback）。LINE Webhook URL 在公網主機後需帶相同路徑。",
  "settings.remoteIm.line.callbackPathPlaceholder": "/line/callback",
  "settings.remoteIm.line.guide.title": "LINE 接入",
  "settings.remoteIm.line.guide.step1": "開啟 LINE Developers Console → 建立 Messaging API 渠道（或選擇既有渠道）。",
  "settings.remoteIm.line.guide.step2": "複製 Channel Secret，並簽發 Channel Access Token；兩者貼到此處。",
  "settings.remoteIm.line.guide.step3": "LINE 需要公網 HTTPS Webhook URL。可選執行建議的 cloudflared 片段（僅輔助，非強制），將 https://… URL + 回呼路徑填入 Messaging API → Webhook。",
  "settings.remoteIm.line.guide.step4": "開啟 Use webhook，盡量限制 allow-from，再點「儲存並連線」並保持 Bridge 執行。",
  "settings.remoteIm.line.guide.softFail": "「測試連線」僅校驗 Channel Secret + Access Token 是否存在（以及連接埠/路徑形態），不代表公網 Webhook 可達，也不代表 LINE 已能回呼你的隧道。",
  "settings.remoteIm.line.publicUrl.title": "LINE 需要公網 HTTPS Webhook",
  "settings.remoteIm.line.publicUrl.body": "LINE 無法存取 127.0.0.1。請用隧道或反向代理暴露本機回呼，再把公網 URL 填入 LINE Developers。",
