  "settings.remoteIm.slack.botTokenHelp": "安裝應用後在 OAuth & Permissions 中的 Bot User OAuth Token（xoxb-…）。預設遮罩儲存，不入日誌。",
  "settings.remoteIm.slack.botTokenPlaceholder": "xoxb-…",
  "settings.remoteIm.slack.appTokenHelp": "在 Basic Information → App-Level Tokens 建立的 App-level Token（xapp-…）。Socket Mode 需要 connections:write 權限。",
  "settings.remoteIm.slack.appTokenPlaceholder": "xapp-…",
  "settings.remoteIm.slack.allowFromHelp": "允許與機器人對話的 Slack 使用者 ID。僅測試時可使用 *，生產環境建議改為明確的 U… ID。",
  "settings.remoteIm.slack.guide.title": "Slack Socket Mode 接入",
  "settings.remoteIm.slack.guide.step1": "打開 api.slack.com/apps → Create New App（From scratch）並選擇工作區。",
  "settings.remoteIm.slack.guide.step2": "開啟 Socket Mode（Settings → Socket Mode）。建立帶 connections:write 的 App-Level Token，複製 xapp- token。",
  "settings.remoteIm.slack.guide.step3": "在 Event Subscriptions 訂閱機器人事件（如 message.im、app_mention）— Socket Mode 無需公網 Request URL。",
  "settings.remoteIm.slack.guide.step4": "新增機器人權限（chat:write、im:history / channels:history 等），Install 到工作區，再複製 Bot User OAuth Token（xoxb-）。",
  "settings.remoteIm.slack.guide.step5": "將兩個 Token 貼到此處，設定允許使用者（生產環境避免 *），再點「儲存並連線」。",
  "settings.remoteIm.slack.guide.softFail": "「測試連線」會校驗雙 Token 格式，並在可連網時對 Bot Token 呼叫 auth.test — 不代表 Socket Mode 已連線，需 Bridge 執行且實例已連結。",
