  "settings.remoteIm.matrix.guide.step2": "建立或使用機器人 / 專用帳號，複製 Access Token（Element：設定 → 說明與關於 → 存取權杖，或透過 API 註冊）。",
  "settings.remoteIm.matrix.guide.step3": "在此貼上 Homeserver URL 與 Access Token。可選：填寫 user id（@bot:server）、限制 allow-from，並設定自動加入 / 代理。",
